import{_ as n,o as t,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"de/cli/run.md","filePath":"de/cli/run.md","lastUpdated":1784903584000}'),r={name:"de/cli/run.md"};function d(s,e,l,h,u,o){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="zweck" tabindex="-1">Zweck <a class="header-anchor" href="#zweck" aria-label="Permalink to &quot;Zweck&quot;">​</a></h2><p>Startet den interaktiven <strong>TUI (Terminal User Interface)</strong>-API-Explorer. Dies ist eine Vollbildanwendung zum Suchen, Durchsuchen, Inspizieren und Aufrufen von API-Endpunkten, ohne das Terminal zu verlassen.</p><h2 id="wann-verwenden" tabindex="-1">Wann verwenden <a class="header-anchor" href="#wann-verwenden" aria-label="Permalink to &quot;Wann verwenden&quot;">​</a></h2><ul><li>Sie möchten Ihre APIs interaktiv erkunden</li><li>Sie müssen nach einem bestimmten Endpunkt über alle Specs hinweg suchen</li><li>Sie möchten die Spec → Collection → Tag → Endpunkt-Hierarchie durchsuchen</li><li>Sie möchten einen API-Aufruf testen, bevor Sie den MCP-Server konfigurieren</li></ul><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="argumente" tabindex="-1">Argumente <a class="header-anchor" href="#argumente" aria-label="Permalink to &quot;Argumente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Position</th><th>Erforderlich</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>Nein</td><td>Arbeitsbereichsverzeichnis. Wenn nicht angegeben, wird über die Pfadauflösungsregeln ermittelt.</td></tr></tbody></table><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h2><p>Keine.</p><h2 id="modi" tabindex="-1">Modi <a class="header-anchor" href="#modi" aria-label="Permalink to &quot;Modi&quot;">​</a></h2><h3 id="suchmodus" tabindex="-1">Suchmodus <a class="header-anchor" href="#suchmodus" aria-label="Permalink to &quot;Suchmodus&quot;">​</a></h3><p>Volltextsuche über alle Endpunkte aller Specs. Unterstützt Filterung nach HTTP-Methode, Tag und Pfad.</p><ul><li>Geben Sie eine Abfrage ein, um nach Endpunktnamen, Pfaden und Beschreibungen zu suchen</li><li>Filtern Sie Ergebnisse nach Methode (GET, POST, PUT, DELETE usw.)</li><li>Zeigen Sie Endpunktdetails mit einem Tastendruck an</li></ul><h3 id="durchsuchen-modus" tabindex="-1">Durchsuchen-Modus <a class="header-anchor" href="#durchsuchen-modus" aria-label="Permalink to &quot;Durchsuchen-Modus&quot;">​</a></h3><p>Baumnavigation durch die Spec-Hierarchie:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpunkt</span></span></code></pre></div><ul><li>Navigieren Sie im Baum nach unten, um bestimmte Endpunkte zu finden</li><li>Zeigen Sie Endpunktdetails an (Parameter, Anforderungstext, Antworten)</li><li>Rufen Sie die API direkt aus der TUI auf</li></ul><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Taste</th><th>Aktion</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Nach oben/unten navigieren</td></tr><tr><td><code>Enter</code></td><td>Auswählen oder öffnen</td></tr><tr><td><code>Esc</code></td><td>Zurückgehen</td></tr><tr><td><code>Tab</code></td><td>Zwischen Such- und Durchsuchen-Modus wechseln</td></tr><tr><td><code>/</code></td><td>Sucheingabe fokussieren</td></tr><tr><td><code>q</code></td><td>Beenden</td></tr></tbody></table><h2 id="uberprufung-nach-dem-befehl" tabindex="-1">Überprüfung nach dem Befehl <a class="header-anchor" href="#uberprufung-nach-dem-befehl" aria-label="Permalink to &quot;Überprüfung nach dem Befehl&quot;">​</a></h2><p>Die TUI lädt alle Specs aus dem Arbeitsbereich. Wenn eine Spec nicht geladen werden kann, wird eine Fehlermeldung in der Oberfläche angezeigt.</p><h2 id="nuancen" tabindex="-1">Nuancen <a class="header-anchor" href="#nuancen" aria-label="Permalink to &quot;Nuancen&quot;">​</a></h2><ul><li><strong>Auto-Init:</strong> Wenn keine Konfigurationsdatei existiert, führt <code>run</code> automatisch zuerst den Init-Assistenten aus.</li><li><strong>Keine Flags:</strong> Der Befehl <code>run</code> hat keine Flags — die gesamte Konfiguration stammt aus dem Arbeitsbereich.</li><li><strong>Terminalgröße:</strong> Die TUI erfordert ein Terminal mit mindestens 80×24 Zeichen. In sehr kleinen Terminals wird sie möglicherweise nicht korrekt dargestellt.</li><li><strong>Abhängigkeiten:</strong> Die TUI verwendet Bubbletea. Sie funktioniert über SSH und in den meisten Terminalemulatoren.</li></ul>',25)])])}const m=n(r,[["render",d]]);export{g as __pageData,m as default};
